// Edge function : génère un rapport PDF pour une intervention validée.
// Design moderne : header avec logo, sections cartonnées, photos avec
// aspect-ratio respecté, footer paginé.
//
// POST { intervention_id }
// Auth : admin OR agent assigné OR client ayant accès au site.

import {
  PDFDocument,
  PDFFont,
  PDFImage,
  PDFPage,
  StandardFonts,
  rgb,
} from 'https://esm.sh/pdf-lib@1.17.1';
import {
  createClient,
  SupabaseClient,
} from 'https://esm.sh/@supabase/supabase-js@2.45.4';
// Logo Les Partenaires DM (PNG 256x256, base64).
// Inline ici car le bundler Supabase Edge Functions n'embarque
// pas les fichiers .ts voisins du point d'entree.
const LOGO_PNG_BASE64 =
  '';

// ============================================================
// CORS + Auth (inlinés volontairement : le bundler Supabase ne
// remonte pas `../_shared/`, donc on duplique ici plutôt que
// d'introduire une dépendance fragile).
// ============================================================

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers':
    'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

type AuthCheckResult =
  | { ok: true; userId: string; admin: SupabaseClient }
  | { ok: false; status: number; error: string };

async function getAuthenticatedUser(req: Request): Promise<AuthCheckResult> {
  const SUPABASE_URL = Deno.env.get('SUPABASE_URL');
  const ANON_KEY = Deno.env.get('SUPABASE_ANON_KEY');
  const SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');

  if (!SUPABASE_URL || !ANON_KEY || !SERVICE_ROLE_KEY) {
    return { ok: false, status: 500, error: 'Server env vars missing' };
  }

  const authHeader = req.headers.get('Authorization');
  if (!authHeader) {
    return { ok: false, status: 401, error: 'Missing Authorization header' };
  }

  const userClient = createClient(SUPABASE_URL, ANON_KEY, {
    global: { headers: { Authorization: authHeader } },
    auth: { autoRefreshToken: false, persistSession: false },
  });

  const { data: userData, error: userError } = await userClient.auth.getUser();
  if (userError || !userData?.user) {
    return { ok: false, status: 401, error: 'Invalid session' };
  }

  const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, {
    auth: { autoRefreshToken: false, persistSession: false },
  });

  return { ok: true, userId: userData.user.id, admin };
}

type Body = { intervention_id?: string };

// ============================================================
// Design system
// ============================================================

const PAGE_W = 595.28; // A4 portrait
const PAGE_H = 841.89;
const MARGIN = 40;
const HEADER_H = 96;
const FOOTER_H = 32;
const CONTENT_TOP = PAGE_H - HEADER_H - 16;
const CONTENT_BOTTOM = MARGIN + FOOTER_H;

type RGB = [number, number, number];
const C_PRIMARY: RGB = [0, 0.137, 0.435]; // #00236F
const C_TEXT: RGB = [0.12, 0.16, 0.22]; // #1E293B
const C_MUTED: RGB = [0.39, 0.45, 0.55]; // #64748B
const C_OUTLINE: RGB = [0.88, 0.91, 0.94];
const C_SURFACE: RGB = [0.96, 0.97, 0.99];
const C_SURFACE_DEEP: RGB = [0.93, 0.95, 0.98];
const C_WHITE: RGB = [1, 1, 1];
const C_SUCCESS: RGB = [0.09, 0.64, 0.29]; // #16A34A
const C_SUCCESS_SOFT: RGB = [0.87, 0.96, 0.89];
const C_WARN: RGB = [0.71, 0.32, 0.04]; // #B45309
const C_WARN_SOFT: RGB = [1, 0.94, 0.83];
const C_DANGER: RGB = [0.86, 0.15, 0.15]; // #DC2626

const rgbOf = (c: RGB) => rgb(c[0], c[1], c[2]);

// ============================================================
// Logo (décodé une fois au cold-start)
// ============================================================
// On stocke le logo en base64 dans logo.ts plutôt que de lire un .png
// depuis le disque, car le bundler Supabase Edge Functions n'inclut
// pas systématiquement les assets binaires du dossier de la fonction
// — `Deno.readFile('./logo.png')` retournait silencieusement vide
// en prod et le PDF se générait sans logo.

let LOGO_BYTES: Uint8Array | null = null;
try {
  LOGO_BYTES = base64ToBytes(LOGO_PNG_BASE64);
} catch (_) {
  LOGO_BYTES = null;
}

function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// ============================================================
// Handler
// ============================================================

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }
  if (req.method !== 'POST') {
    return json({ error: 'Method not allowed' }, 405);
  }

  const auth = await getAuthenticatedUser(req);
  if (!auth.ok) return json({ error: auth.error }, auth.status);
  const { admin, userId } = auth;

  let body: Body;
  try {
    body = await req.json();
  } catch {
    return json({ error: 'Invalid JSON body' }, 400);
  }
  if (!body.intervention_id) {
    return json({ error: 'intervention_id is required' }, 400);
  }
  const interventionId = body.intervention_id;

  // ----- 1) Charge intervention + autorise -----
  const { data: iv, error: ivErr } = await admin
    .from('interventions')
    .select(
      `id, site_id, agent_id, scheduled_at, validated_at, status,
       admin_summary, admin_details, global_result, pdf_url,
       site:sites ( id, name, address, client:clients ( id, name ) ),
       agent:profiles!interventions_agent_id_fkey ( id, full_name )`
    )
    .eq('id', interventionId)
    .maybeSingle();

  if (ivErr || !iv) return json({ error: 'Intervention not found' }, 404);

  const { data: profile, error: profErr } = await admin
    .from('profiles')
    .select('role, client_id')
    .eq('id', userId)
    .maybeSingle();
  const isAdmin = profile?.role === 'admin';
  const isAgent = (iv as any).agent_id === userId;

  let isClientAllowed = false;
  if (!isAdmin && !isAgent && profile?.role === 'client') {
    if (profile.client_id) {
      const { data: siteRow } = await admin
        .from('sites')
        .select('client_id')
        .eq('id', (iv as any).site_id)
        .maybeSingle();
      if (siteRow?.client_id && siteRow.client_id === profile.client_id) {
        isClientAllowed = true;
      }
    }
    if (!isClientAllowed) {
      const { count } = await admin
        .from('client_site_access')
        .select('*', { count: 'exact', head: true })
        .eq('client_profile_id', userId)
        .eq('site_id', (iv as any).site_id);
      isClientAllowed = (count ?? 0) > 0;
    }
  }

  if (!isAdmin && !isAgent && !isClientAllowed) {
    return json(
      {
        error: `Forbidden — userId=${userId}, role=${profile?.role ?? 'null'}, ` +
          `profile.client_id=${profile?.client_id ?? 'null'}, ` +
          `iv.site_id=${(iv as any).site_id ?? 'null'}` +
          (profErr ? `, profile_err=${profErr.message}` : ''),
      },
      403
    );
  }

  // ----- 2) Charge tasks + results + media -----
  let tasksRes = await admin
    .from('checklist_tasks')
    .select('*')
    .eq('intervention_id', interventionId)
    .order('order_index', { ascending: true });
  if (!tasksRes.data || tasksRes.data.length === 0) {
    tasksRes = await admin
      .from('checklist_tasks')
      .select('*')
      .eq('site_id', (iv as any).site_id)
      .is('intervention_id', null)
      .order('order_index', { ascending: true });
  }
  const tasks = tasksRes.data ?? [];

  const { data: resultsRows } = await admin
    .from('checklist_results')
    .select('task_id, is_done')
    .eq('intervention_id', interventionId);
  const resultsMap = new Map<string, boolean>();
  for (const r of resultsRows ?? []) {
    resultsMap.set((r as any).task_id, !!(r as any).is_done);
  }

  // Toutes les photos liées à l'intervention (cf. migration 0019, le flag
  // is_validated n'est plus une condition gating).
  const { data: mediaRows } = await admin
    .from('media')
    .select('id, url, type, zone, taken_at')
    .eq('intervention_id', interventionId)
    .order('taken_at', { ascending: true });
  const media = (mediaRows ?? []) as Array<{
    id: string;
    url: string;
    type: 'before' | 'after' | 'anomaly';
    zone: string | null;
  }>;

  // ============================================================
  // 3) PDF
  // ============================================================

  const pdf = await PDFDocument.create();
  const font = await pdf.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdf.embedFont(StandardFonts.HelveticaBold);
  const logoImg = LOGO_BYTES
    ? await pdf.embedPng(LOGO_BYTES).catch(() => null)
    : null;

  // Layout state
  let page = pdf.addPage([PAGE_W, PAGE_H]);
  let y = CONTENT_TOP;

  drawHeader(page, logoImg, font, fontBold);

  const newPage = () => {
    page = pdf.addPage([PAGE_W, PAGE_H]);
    drawHeader(page, logoImg, font, fontBold);
    y = CONTENT_TOP;
  };

  const ensure = (needed: number) => {
    if (y - needed < CONTENT_BOTTOM) newPage();
  };

  // ----- Cover : status pill + site + adresse -----
  const ivAny = iv as any;
  const hadPdfUrl = !!ivAny.pdf_url;
  const siteName = ivAny.site?.name ?? 'Site inconnu';
  const clientName = ivAny.site?.client?.name ?? '—';
  const agentName = ivAny.agent?.full_name ?? 'Non assigne';
  const validatedDate = ivAny.validated_at
    ? formatDate(ivAny.validated_at)
    : '—';
  const scheduledDate = ivAny.scheduled_at
    ? formatDateTime(ivAny.scheduled_at)
    : '—';

  const isToImprove = ivAny.global_result === 'to_improve';
  const statusLabel = isToImprove ? 'A AMELIORER' : 'INTERVENTION OK';
  const statusFill: RGB = isToImprove ? C_WARN_SOFT : C_SUCCESS_SOFT;
  const statusTextColor: RGB = isToImprove ? C_WARN : C_SUCCESS;

  drawPill(
    page,
    PAGE_W - MARGIN,
    y,
    statusLabel,
    fontBold,
    9.5,
    statusFill,
    statusTextColor,
    'right'
  );
  y -= 30;

  // Site name (h1)
  drawSingleLine(
    page,
    stripAccents(siteName),
    MARGIN,
    y,
    fontBold,
    24,
    C_PRIMARY
  );
  y -= 28;

  // Address
  if (ivAny.site?.address) {
    drawSingleLine(
      page,
      stripAccents(ivAny.site.address),
      MARGIN,
      y,
      font,
      11,
      C_MUTED
    );
    y -= 16;
  }
  y -= 14;

  // ----- Meta grid (2 cards par ligne, 2 lignes) -----
  const META_GAP = 12;
  const META_COL_W = (PAGE_W - 2 * MARGIN - META_GAP) / 2;
  const META_ITEM_H = 52;
  const metaItems: { label: string; value: string }[] = [
    { label: 'CLIENT', value: stripAccents(clientName) },
    { label: 'AGENT RESPONSABLE', value: stripAccents(agentName) },
    { label: 'INTERVENTION PLANIFIEE', value: scheduledDate },
    { label: 'VALIDEE LE', value: validatedDate },
  ];
  for (let i = 0; i < metaItems.length; i += 2) {
    ensure(META_ITEM_H + 6);
    const left = metaItems[i];
    const right = metaItems[i + 1];
    drawMetaCard(
      page,
      MARGIN,
      y,
      META_COL_W,
      META_ITEM_H,
      left.label,
      left.value,
      font,
      fontBold
    );
    if (right) {
      drawMetaCard(
        page,
        MARGIN + META_COL_W + META_GAP,
        y,
        META_COL_W,
        META_ITEM_H,
        right.label,
        right.value,
        font,
        fontBold
      );
    }
    y -= META_ITEM_H + META_GAP;
  }

  // ----- Résumé -----
  if (ivAny.admin_summary && String(ivAny.admin_summary).trim()) {
    y -= 6;
    ensure(50);
    drawSectionTitle(page, "Resume de l'intervention", MARGIN, y, fontBold);
    y -= 26;
    y = drawTextBlock(
      page,
      stripAccents(String(ivAny.admin_summary)),
      MARGIN,
      y,
      PAGE_W - 2 * MARGIN,
      font,
      10.5,
      C_TEXT,
      ensure
    );
  }

  // ----- Détails complémentaires -----
  if (ivAny.admin_details && String(ivAny.admin_details).trim()) {
    y -= 16;
    ensure(50);
    drawSectionTitle(page, 'Details complementaires', MARGIN, y, fontBold);
    y -= 26;
    y = drawTextBlock(
      page,
      stripAccents(String(ivAny.admin_details)),
      MARGIN,
      y,
      PAGE_W - 2 * MARGIN,
      font,
      10.5,
      C_TEXT,
      ensure
    );
  }

  // ----- Tâches effectuées -----
  y -= 22;
  ensure(60);
  drawSectionTitle(page, 'Taches effectuees', MARGIN, y, fontBold);
  y -= 26;

  const tasksByZone = new Map<string, typeof tasks>();
  for (const t of tasks) {
    const k = (t as any).zone ?? 'Général';
    const list = tasksByZone.get(k) ?? [];
    list.push(t);
    tasksByZone.set(k, list);
  }

  if (tasksByZone.size === 0) {
    drawTextLineMuted(
      page,
      'Aucune tache definie pour cette intervention.',
      MARGIN + 4,
      y - 4,
      font
    );
    y -= 22;
  }

  for (const [zone, items] of tasksByZone.entries()) {
    const total = items.length;
    const done = (items as any[]).filter((t) =>
      resultsMap.get(t.id)
    ).length;
    ensure(36);
    drawZoneHeader(
      page,
      MARGIN,
      y,
      PAGE_W - 2 * MARGIN,
      stripAccents(zone),
      `${done}/${total}`,
      fontBold,
      font
    );
    y -= 24;

    for (const t of items as any[]) {
      const lines = wrapByWidth(
        stripAccents(t.label as string),
        font,
        10,
        PAGE_W - 2 * MARGIN - 32
      );
      const blockH = Math.max(18, lines.length * 13 + 6);
      ensure(blockH);
      drawTaskRow(
        page,
        MARGIN,
        y,
        lines,
        !!resultsMap.get(t.id),
        font,
        fontBold
      );
      y -= blockH;
    }
    y -= 10;
  }

  // ----- Preuves photographiques -----
  if (media.length > 0) {
    y -= 14;
    ensure(60);
    drawSectionTitle(page, 'Preuves photographiques', MARGIN, y, fontBold);
    y -= 26;

    const TILE_GAP = 14;
    const TILE_W = (PAGE_W - 2 * MARGIN - TILE_GAP) / 2;
    const TILE_H = TILE_W * 0.72; // ratio confortable pour photos paysage et portrait

    const mediaByZone = new Map<string, typeof media>();
    for (const m of media) {
      const k = m.zone ?? 'Général';
      const list = mediaByZone.get(k) ?? [];
      list.push(m);
      mediaByZone.set(k, list);
    }

    for (const [zone, items] of mediaByZone.entries()) {
      ensure(40);
      drawZoneHeader(
        page,
        MARGIN,
        y,
        PAGE_W - 2 * MARGIN,
        stripAccents(zone),
        `${items.length} photo${items.length > 1 ? 's' : ''}`,
        fontBold,
        font
      );
      y -= 26;

      let col = 0;
      for (const m of items) {
        if (col === 0) ensure(TILE_H + TILE_GAP);
        const tileX = MARGIN + col * (TILE_W + TILE_GAP);
        const tileY = y - TILE_H;

        let embedded: PDFImage | null = null;
        try {
          const imgBytes = await fetchImageBytes(m.url, admin);
          try {
            embedded = await pdf.embedJpg(imgBytes);
          } catch {
            embedded = await pdf.embedPng(imgBytes);
          }
        } catch (_) {
          embedded = null;
        }

        if (embedded) {
          drawPhotoTile(
            page,
            tileX,
            tileY,
            TILE_W,
            TILE_H,
            embedded,
            m.type,
            fontBold
          );
        } else {
          drawPhotoPlaceholder(page, tileX, tileY, TILE_W, TILE_H, font);
        }

        col = (col + 1) % 2;
        if (col === 0) y -= TILE_H + TILE_GAP;
      }
      if (col !== 0) y -= TILE_H + TILE_GAP;
      y -= 6;
    }
  }

  // ----- Footer paginé (after all content) -----
  const pages = pdf.getPages();
  for (let i = 0; i < pages.length; i++) {
    drawFooter(pages[i], i + 1, pages.length, font);
  }

  // ============================================================
  // 4) Upload + signed URL + persist
  // ============================================================

  const pdfBytes = await pdf.save();
  const path = `${interventionId}/report.pdf`;
  const { error: upErr } = await admin.storage
    .from('reports')
    .upload(path, pdfBytes, {
      contentType: 'application/pdf',
      upsert: true,
    });
  if (upErr) {
    return json({ error: `Upload failed: ${upErr.message}` }, 500);
  }

  const { data: signed, error: signErr } = await admin.storage
    .from('reports')
    .createSignedUrl(path, 60 * 60 * 24 * 365);
  if (signErr || !signed?.signedUrl) {
    return json({ error: signErr?.message ?? 'Failed to sign URL' }, 500);
  }

  await admin
    .from('interventions')
    .update({ pdf_url: signed.signedUrl })
    .eq('id', interventionId);

  if (!hadPdfUrl) {
    triggerNotification(req, 'report_available', interventionId);
    triggerReportEmail(req, interventionId);
  }

  return json({ ok: true, signed_url: signed.signedUrl }, 200);
});

// ============================================================
// Drawing primitives
// ============================================================

const LOGO_BOX = 56;

function drawHeader(
  page: PDFPage,
  logo: PDFImage | null,
  font: PDFFont,
  fontBold: PDFFont
) {
  // Logo top-left, aspect-ratio preserved, centered in a 56x56 box
  if (logo) {
    const r = logo.width / logo.height;
    let w = LOGO_BOX;
    let h = LOGO_BOX;
    if (r > 1) h = LOGO_BOX / r;
    else if (r < 1) w = LOGO_BOX * r;
    const boxTop = PAGE_H - 22;
    const boxX = MARGIN;
    const x = boxX + (LOGO_BOX - w) / 2;
    const yy = boxTop - LOGO_BOX + (LOGO_BOX - h) / 2;
    page.drawImage(logo, { x, y: yy, width: w, height: h });
  }

  // Brand label right of logo
  const brandX = MARGIN + LOGO_BOX + 14;
  page.drawText('LES PARTENAIRES DM', {
    x: brandX,
    y: PAGE_H - 38,
    size: 14,
    font: fontBold,
    color: rgbOf(C_PRIMARY),
  });
  page.drawText("Rapport d'intervention", {
    x: brandX,
    y: PAGE_H - 56,
    size: 10,
    font,
    color: rgbOf(C_MUTED),
  });

  // Generation date top-right
  const now = new Date().toLocaleDateString('fr-FR', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  });
  const label = `Genere le ${now}`;
  const lblW = font.widthOfTextAtSize(label, 9);
  page.drawText(label, {
    x: PAGE_W - MARGIN - lblW,
    y: PAGE_H - 46,
    size: 9,
    font,
    color: rgbOf(C_MUTED),
  });

  // Separator (subtle gradient simulated by stacking two thin rectangles)
  page.drawRectangle({
    x: MARGIN,
    y: PAGE_H - HEADER_H,
    width: PAGE_W - 2 * MARGIN,
    height: 1.2,
    color: rgbOf(C_PRIMARY),
  });
  page.drawRectangle({
    x: MARGIN,
    y: PAGE_H - HEADER_H - 2,
    width: PAGE_W - 2 * MARGIN,
    height: 0.6,
    color: rgbOf(C_OUTLINE),
  });
}

function drawFooter(
  page: PDFPage,
  current: number,
  total: number,
  font: PDFFont
) {
  const y = MARGIN - 6;
  // Separator
  page.drawRectangle({
    x: MARGIN,
    y: y + 20,
    width: PAGE_W - 2 * MARGIN,
    height: 0.5,
    color: rgbOf(C_OUTLINE),
  });
  // Brand
  page.drawText('Les Partenaires DM - rapport confidentiel', {
    x: MARGIN,
    y,
    size: 8,
    font,
    color: rgbOf(C_MUTED),
  });
  // Page X / Y
  const pageLabel = `Page ${current} / ${total}`;
  const w = font.widthOfTextAtSize(pageLabel, 8);
  page.drawText(pageLabel, {
    x: PAGE_W - MARGIN - w,
    y,
    size: 8,
    font,
    color: rgbOf(C_MUTED),
  });
}

function drawSingleLine(
  page: PDFPage,
  text: string,
  x: number,
  y: number,
  font: PDFFont,
  size: number,
  color: RGB
) {
  page.drawText(text, { x, y, size, font, color: rgbOf(color) });
}

function drawTextLineMuted(
  page: PDFPage,
  text: string,
  x: number,
  y: number,
  font: PDFFont
) {
  page.drawText(stripAccents(text), {
    x,
    y,
    size: 10,
    font,
    color: rgbOf(C_MUTED),
  });
}

function drawPill(
  page: PDFPage,
  x: number,
  y: number,
  label: string,
  font: PDFFont,
  size: number,
  fill: RGB,
  textColor: RGB,
  anchor: 'left' | 'right' = 'left'
) {
  const padX = 12;
  const padY = 5;
  const textW = font.widthOfTextAtSize(label, size);
  const w = textW + 2 * padX;
  const h = size + 2 * padY;
  const realX = anchor === 'right' ? x - w : x;
  page.drawRectangle({
    x: realX,
    y: y - h,
    width: w,
    height: h,
    color: rgbOf(fill),
  });
  page.drawText(label, {
    x: realX + padX,
    y: y - h + padY + 1,
    size,
    font,
    color: rgbOf(textColor),
  });
}

function drawSectionTitle(
  page: PDFPage,
  label: string,
  x: number,
  y: number,
  fontBold: PDFFont
) {
  // Accent bar on the left
  page.drawRectangle({
    x,
    y: y - 14,
    width: 3,
    height: 18,
    color: rgbOf(C_PRIMARY),
  });
  page.drawText(stripAccents(label), {
    x: x + 10,
    y,
    size: 13,
    font: fontBold,
    color: rgbOf(C_PRIMARY),
  });
}

function drawZoneHeader(
  page: PDFPage,
  x: number,
  y: number,
  w: number,
  label: string,
  badge: string,
  fontBold: PDFFont,
  font: PDFFont
) {
  const h = 22;
  page.drawRectangle({
    x,
    y: y - h + 6,
    width: w,
    height: h,
    color: rgbOf(C_SURFACE_DEEP),
  });
  page.drawText(stripAccents(label).toUpperCase(), {
    x: x + 12,
    y: y - 8,
    size: 9,
    font: fontBold,
    color: rgbOf(C_PRIMARY),
  });
  const badgeW = font.widthOfTextAtSize(badge, 9);
  page.drawText(badge, {
    x: x + w - badgeW - 12,
    y: y - 8,
    size: 9,
    font: fontBold,
    color: rgbOf(C_MUTED),
  });
}

function drawTaskRow(
  page: PDFPage,
  x: number,
  y: number,
  lines: string[],
  done: boolean,
  font: PDFFont,
  fontBold: PDFFont
) {
  // Checkbox aligned to the first line
  const boxSize = 11;
  const boxX = x + 4;
  const boxY = y - boxSize - 1;
  page.drawRectangle({
    x: boxX,
    y: boxY,
    width: boxSize,
    height: boxSize,
    color: done ? rgbOf(C_PRIMARY) : rgbOf(C_WHITE),
    borderColor: done ? rgbOf(C_PRIMARY) : rgbOf(C_OUTLINE),
    borderWidth: 1,
  });
  if (done) {
    // Simple check mark (Helvetica doesn't have a real ✓, use 'v' as placeholder)
    page.drawText('v', {
      x: boxX + 2.5,
      y: boxY + 1.5,
      size: 9,
      font: fontBold,
      color: rgbOf(C_WHITE),
    });
  }

  const textColor: RGB = done ? C_TEXT : C_MUTED;
  let ty = y - 10;
  for (const line of lines) {
    page.drawText(line, {
      x: x + 22,
      y: ty,
      size: 10,
      font,
      color: rgbOf(textColor),
    });
    ty -= 13;
  }
}

function drawMetaCard(
  page: PDFPage,
  x: number,
  y: number,
  w: number,
  h: number,
  label: string,
  value: string,
  font: PDFFont,
  fontBold: PDFFont
) {
  // Card
  page.drawRectangle({
    x,
    y: y - h,
    width: w,
    height: h,
    color: rgbOf(C_SURFACE),
    borderColor: rgbOf(C_OUTLINE),
    borderWidth: 0.6,
  });
  // Accent bar (left edge)
  page.drawRectangle({
    x,
    y: y - h,
    width: 2.5,
    height: h,
    color: rgbOf(C_PRIMARY),
  });
  // Label
  page.drawText(stripAccents(label), {
    x: x + 12,
    y: y - 16,
    size: 7.5,
    font: fontBold,
    color: rgbOf(C_MUTED),
  });
  // Value — truncate to fit width
  const valueText = truncateToWidth(value, fontBold, 11.5, w - 24);
  page.drawText(valueText, {
    x: x + 12,
    y: y - 36,
    size: 11.5,
    font: fontBold,
    color: rgbOf(C_TEXT),
  });
}

function drawTextBlock(
  page: PDFPage,
  text: string,
  x: number,
  y: number,
  w: number,
  font: PDFFont,
  size: number,
  color: RGB,
  ensure: (n: number) => void
): number {
  const padding = 14;
  const innerW = w - 2 * padding;
  const lineH = size + 4.5;

  const lines = text
    .split(/\r?\n/)
    .flatMap((p) => (p.trim() === '' ? [''] : wrapByWidth(p, font, size, innerW)));

  // If the block is taller than available space, draw with overflow per chunk.
  // For simplicity we render the entire block in one card, allowing a single
  // page break before the block.
  const totalH = lines.length * lineH + 2 * padding;
  ensure(Math.min(totalH, CONTENT_TOP - CONTENT_BOTTOM));

  page.drawRectangle({
    x,
    y: y - totalH,
    width: w,
    height: totalH,
    color: rgbOf(C_SURFACE),
    borderColor: rgbOf(C_OUTLINE),
    borderWidth: 0.6,
  });

  let ty = y - padding - size + 2;
  for (const line of lines) {
    page.drawText(line, {
      x: x + padding,
      y: ty,
      size,
      font,
      color: rgbOf(color),
    });
    ty -= lineH;
  }

  return y - totalH;
}

function drawPhotoTile(
  page: PDFPage,
  x: number,
  y: number,
  w: number,
  h: number,
  img: PDFImage,
  type: 'before' | 'after' | 'anomaly',
  fontBold: PDFFont
) {
  // Background card (light gray so letterboxing reads as intentional)
  page.drawRectangle({
    x,
    y,
    width: w,
    height: h,
    color: rgbOf(C_SURFACE_DEEP),
    borderColor: rgbOf(C_OUTLINE),
    borderWidth: 0.6,
  });

  // Aspect-ratio preserving fit (contain)
  const imgR = img.width / img.height;
  const tileR = w / h;
  let drawW: number;
  let drawH: number;
  if (imgR > tileR) {
    drawW = w;
    drawH = w / imgR;
  } else {
    drawH = h;
    drawW = h * imgR;
  }
  const drawX = x + (w - drawW) / 2;
  const drawY = y + (h - drawH) / 2;
  page.drawImage(img, { x: drawX, y: drawY, width: drawW, height: drawH });

  // Type badge (top-left)
  const labels: Record<string, string> = {
    before: 'AVANT',
    after: 'APRES',
    anomaly: 'ANOMALIE',
  };
  const fills: Record<string, RGB> = {
    before: C_DANGER,
    after: C_PRIMARY,
    anomaly: C_WARN,
  };
  const label = labels[type] ?? type.toUpperCase();
  const fontSize = 8;
  const textW = fontBold.widthOfTextAtSize(label, fontSize);
  const badgeW = textW + 14;
  const badgeH = fontSize + 8;
  const bx = x + 8;
  const by = y + h - badgeH - 8;
  page.drawRectangle({
    x: bx,
    y: by,
    width: badgeW,
    height: badgeH,
    color: rgbOf(fills[type] ?? C_PRIMARY),
  });
  page.drawText(label, {
    x: bx + 7,
    y: by + 4,
    size: fontSize,
    font: fontBold,
    color: rgbOf(C_WHITE),
  });
}

function drawPhotoPlaceholder(
  page: PDFPage,
  x: number,
  y: number,
  w: number,
  h: number,
  font: PDFFont
) {
  page.drawRectangle({
    x,
    y,
    width: w,
    height: h,
    color: rgbOf(C_SURFACE_DEEP),
    borderColor: rgbOf(C_OUTLINE),
    borderWidth: 0.6,
  });
  const msg = 'Image indisponible';
  const size = 9;
  const tw = font.widthOfTextAtSize(msg, size);
  page.drawText(msg, {
    x: x + (w - tw) / 2,
    y: y + h / 2 - size / 2,
    size,
    font,
    color: rgbOf(C_MUTED),
  });
}

// ============================================================
// Image fetch + path extraction
// ============================================================

async function fetchImageBytes(
  urlOrPath: string,
  admin: SupabaseClient
): Promise<Uint8Array> {
  // 1) tentative directe via signed URL stockée
  if (urlOrPath.startsWith('http')) {
    try {
      const r = await fetch(urlOrPath);
      if (r.ok) return new Uint8Array(await r.arrayBuffer());
    } catch (_) {
      /* tombe en fallback */
    }
  }

  // 2) fallback : download via service-role (protège des URLs expirées)
  const path = extractStoragePath(urlOrPath);
  if (!path) throw new Error('Image fetch failed and no path extractable');
  const { data: blob, error } = await admin.storage
    .from('media')
    .download(path);
  if (error || !blob) {
    throw new Error(`Storage download failed: ${error?.message ?? 'unknown'}`);
  }
  return new Uint8Array(await blob.arrayBuffer());
}

function extractStoragePath(urlOrPath: string): string | null {
  if (!urlOrPath) return null;
  if (!urlOrPath.startsWith('http')) return urlOrPath;
  const match = urlOrPath.match(/\/(?:sign|object|public)\/media\/([^?]+)/);
  if (!match) return null;
  try {
    return decodeURIComponent(match[1]);
  } catch {
    return match[1];
  }
}

// ============================================================
// Text utils
// ============================================================

/** pdf-lib + StandardFonts ne supportent pas les accents : on les ramène
 *  à de l'ASCII pour éviter les WinAnsi encoding errors. */
function stripAccents(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[œŒ]/g, 'oe')
    .replace(/[æÆ]/g, 'ae')
    .replace(/[–—]/g, '-')
    .replace(/[’‘]/g, "'")
    .replace(/[“”]/g, '"');
}

function wrapByWidth(
  text: string,
  font: PDFFont,
  size: number,
  maxW: number
): string[] {
  const words = text.split(/\s+/).filter(Boolean);
  const lines: string[] = [];
  let current = '';
  for (const w of words) {
    const candidate = current ? `${current} ${w}` : w;
    if (font.widthOfTextAtSize(candidate, size) > maxW) {
      if (current) lines.push(current);
      // Si un mot seul dépasse, on le coupe brutalement
      if (font.widthOfTextAtSize(w, size) > maxW) {
        const chunks = breakLongWord(w, font, size, maxW);
        for (let i = 0; i < chunks.length - 1; i++) lines.push(chunks[i]);
        current = chunks[chunks.length - 1];
      } else {
        current = w;
      }
    } else {
      current = candidate;
    }
  }
  if (current) lines.push(current);
  return lines.length > 0 ? lines : [''];
}

function breakLongWord(
  word: string,
  font: PDFFont,
  size: number,
  maxW: number
): string[] {
  const out: string[] = [];
  let buf = '';
  for (const ch of word) {
    const candidate = buf + ch;
    if (font.widthOfTextAtSize(candidate, size) > maxW) {
      if (buf) out.push(buf);
      buf = ch;
    } else {
      buf = candidate;
    }
  }
  if (buf) out.push(buf);
  return out.length > 0 ? out : [word];
}

function truncateToWidth(
  text: string,
  font: PDFFont,
  size: number,
  maxW: number
): string {
  if (font.widthOfTextAtSize(text, size) <= maxW) return text;
  const ellipsis = '...';
  let lo = 0;
  let hi = text.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (font.widthOfTextAtSize(text.slice(0, mid) + ellipsis, size) <= maxW) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }
  return text.slice(0, lo).trimEnd() + ellipsis;
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('fr-FR', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  });
}

function formatDateTime(iso: string): string {
  return new Date(iso).toLocaleString('fr-FR', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function json(payload: unknown, status: number) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

function triggerReportEmail(req: Request, interventionId: string): void {
  const SUPABASE_URL = Deno.env.get('SUPABASE_URL');
  const authHeader = req.headers.get('Authorization');
  if (!SUPABASE_URL || !authHeader) return;

  const task = fetch(`${SUPABASE_URL}/functions/v1/send-report-email`, {
    method: 'POST',
    headers: {
      Authorization: authHeader,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ intervention_id: interventionId }),
  })
    .then(async (r) => {
      if (!r.ok) {
        const txt = await r.text().catch(() => '');
        console.error('[generate-report] email trigger failed:', r.status, txt);
      }
    })
    .catch((e) => {
      console.error('[generate-report] email trigger error:', e);
    });

  // @ts-ignore EdgeRuntime n'est pas dans les types par défaut
  if (typeof EdgeRuntime !== 'undefined' && EdgeRuntime?.waitUntil) {
    // @ts-ignore
    EdgeRuntime.waitUntil(task);
  }
}

function triggerNotification(req: Request, type: string, entityId: string): void {
  const SUPABASE_URL = Deno.env.get('SUPABASE_URL');
  const authHeader = req.headers.get('Authorization');
  if (!SUPABASE_URL || !authHeader) return;

  const task = fetch(`${SUPABASE_URL}/functions/v1/dispatch-notification`, {
    method: 'POST',
    headers: {
      Authorization: authHeader,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ type, entity_id: entityId }),
  }).catch((e) => {
    console.error('[generate-report] notification error:', e);
  });

  // @ts-ignore EdgeRuntime n'est pas dans les types par défaut
  if (typeof EdgeRuntime !== 'undefined' && EdgeRuntime?.waitUntil) {
    // @ts-ignore
    EdgeRuntime.waitUntil(task);
  }
}
